"""Independent expected constants, not expectations generated by the extractor."""
from decimal import Decimal
import json
from pathlib import Path
import pytest
from quarterfill.concepts import BY_NAME
from quarterfill.sec import SECClient
from quarterfill.research import Research
from quarterfill.validation import validate

EXPECTED=json.loads((Path(__file__).parent/'fixtures/overhaul_expected.json').read_text())


@pytest.fixture(scope='module',params=list(EXPECTED['companies']))
def reviewed_company(request):
    ticker=request.param
    spec=EXPECTED['companies'][ticker]
    client=SECClient()
    company,submissions=client.company(spec['cik'])
    research=Research(client,company,submissions)
    research.investigate(2025)
    research.version_policy='original'
    return ticker,spec,research


def test_original_statement_amounts_are_present_and_document_matched(reviewed_company):
    ticker,spec,research=reviewed_company
    for name,expected in spec['metrics'].items():
        cell=research.cell(name,2025,4 if BY_NAME[name].kind=='instant' else 0)
        assert cell.value==Decimal(expected),(ticker,name,cell.audit())
        assert cell.verified,(ticker,name)
        assert all(f.url.startswith('https://www.sec.gov/Archives/') for f in cell.inputs)
        assert all(f.section for f in cell.inputs)


def test_reported_balance_sheet_reconciles_and_bank_formulas_are_guarded(reviewed_company):
    ticker,spec,research=reviewed_company
    cells=[research.cell(n,2025,4) for n in ('Total assets','Total liabilities','Equity including noncontrolling interests',
                                          'Temporary equity','Redeemable noncontrolling interests')]
    check=validate(cells)[0]
    assert check.status=='Passed',(ticker,check)
    if ticker=='JPM':
        assert research.cell('Gross profit',2025,0).value is None
        assert research.cell('Gross profit',2025,0).accounting_status=='Unavailable'


def test_real_notes_and_custom_combined_scopes_remain_distinct(reviewed_company):
    ticker,spec,research=reviewed_company
    if ticker=='WMT':
        cell=research.cell('Indefinite-lived intangible assets',2025,4)
        assert cell.value==Decimal('4500000000') and cell.verified
        assert any('indefinite-lived intangible assets' in f.section for f in cell.inputs)
    if ticker=='MSFT':
        custom=[f for f in research.facts if f.concept=='msft:AcquisitionsNetOfCashAcquiredAndPurchasesOfIntangibleAndOtherAssets'
                and f.start=='2024-07-01' and f.end=='2025-06-30' and f.verified]
        assert custom and custom[0].value==Decimal('5978000000')
        assert all(f.concept!=custom[0].concept for f in research.cell('Acquisitions',2025,0).inputs)
